INSERT OR REPLACE INTO profile (id, full_name, nickname, title, bio_short, bio_long, location, avatar, avatar_id, cover_image, cover_image_id, resume_url, meta_description, created_at, updated_at) VALUES (
    '67e993bc0007c2156562',
    'Jamal Ibrahim Umar',
    'CaptJay',
    'Software Engineer',
    'I spend most of my time building things while thoroughly enjoying the process.
There''s nothing else I''d rather be doing.',
    'Since my childhood, I''ve been a tech geek with an insatiable curiosity for all things, especially digital. It was clear to me from an early age that my future lay in the world of technology; I just hadn''t quite figured out the specific path I wanted to take.

My proper journey into the tech world began with me spending countless hours tinkering with custom ROMs, bricking and unbricking my devices. This hands-on experience not only further fueled my passion for technology but also sparked my desire to dive deeper into the realm of software development.

In 2019, I made the decision to pursue a career in software engineering. Following my university education, I embarked on a transformative journey by enrolling in the **ALX Software Engineering** program.

Since then, I''ve been dedicated to expanding my knowledge and skills, constantly pushing the boundaries of what I can achieve and building things while thoroughly enjoying the process

I proudly stand as a Software Engineer with, a deep-rooted passion for technology, a commitment to lifelong learning and a desire to make a meaningful impact through my work.
',
    'Kaduna, Nigeria',
    '/profile/default-avatar.webp',
    NULL,
    NULL,
    NULL,
    NULL,
    'Software Engineer currently using Laravel, Next.js and Flutter to Build scalable web and mobile applications. While exploring other modern technologies. Based in Kaduna and Abuja, Nigeria.',
    '2025-03-30T18:55:56.312+00:00',
    '2025-07-17T22:58:01.451+00:00'
  );
